 5	final class AdjacencyMatrix {
 6	    private static final int NO_EDGE = 0;
 7	
 8	    private final int[][] rows;
 9	
10	    private AdjacencyMatrix(int[][] rows) {
11	        this.rows = rows;
12	    }
13	
14	    static AdjacencyMatrix fromRows(int[][] rows) {
15	        validate(rows);
16	        return new AdjacencyMatrix(copyRows(rows));
17	    }
18	
19	    int vertexCount() {
20	        return rows.length;
21	    }
22	
23	    List<Neighbor> neighborsOf(int vertex) {
24	        List<Neighbor> neighbors = new ArrayList<>();
25	
26	        for (int candidateVertex = 0; candidateVertex < rows[vertex].length; candidateVertex++) {
27	            int edgeWeight = rows[vertex][candidateVertex];
28	            if (edgeWeight != NO_EDGE) {
29	                neighbors.add(new Neighbor(candidateVertex, edgeWeight));
30	            }
31	        }
32	
33	        return List.copyOf(neighbors);
34	    }
35	
36	    private static void validate(int[][] rows) {
37	        if (rows == null || rows.length == 0) {
38	            throw new IllegalArgumentException("Graph must contain at least one vertex.");
39	        }
40	
41	        for (int row = 0; row < rows.length; row++) {
42	            if (rows[row] == null || rows[row].length != rows.length) {
43	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
44	            }
45	        }
46	
47	        for (int row = 0; row < rows.length; row++) {
48	            if (rows[row][row] != NO_EDGE) {
49	                throw new IllegalArgumentException("Graph diagonal must be zero.");
50	            }
51	
52	            for (int column = row + 1; column < rows.length; column++) {
53	                if (rows[row][column] != rows[column][row]) {
54	                    throw new IllegalArgumentException("Graph must be undirected and symmetric.");
55	                }
56	            }
57	        }
58	    }
59	
60	    private static int[][] copyRows(int[][] rows) {
61	        int[][] copiedRows = new int[rows.length][];
62	
63	        for (int row = 0; row < rows.length; row++) {
64	            copiedRows[row] = Arrays.copyOf(rows[row], rows[row].length);
65	        }
66	
67	        return copiedRows;
68	    }
69	}

