 4	final class NeighborListGraph implements Graph {
 5	    private final List<List<Neighbor>> neighborsByVertex;
 6	
 7	    private NeighborListGraph(List<List<Neighbor>> neighborsByVertex) {
 8	        this.neighborsByVertex = copyNeighbors(neighborsByVertex);
 9	    }
10	
11	    static Graph fromAdjacencyMatrix(AdjacencyMatrix adjacencyMatrix) {
12	        List<List<Neighbor>> neighborsByVertex = new ArrayList<>(adjacencyMatrix.vertexCount());
13	
14	        for (int vertex = 0; vertex < adjacencyMatrix.vertexCount(); vertex++) {
15	            neighborsByVertex.add(adjacencyMatrix.neighborsOf(vertex));
16	        }
17	
18	        return new NeighborListGraph(neighborsByVertex);
19	    }
20	
21	    @Override
22	    public int vertexCount() {
23	        return neighborsByVertex.size();
24	    }
25	
26	    @Override
27	    public List<Neighbor> neighborsOf(int vertex) {
28	        return neighborsByVertex.get(vertex);
29	    }
30	
31	    private static List<List<Neighbor>> copyNeighbors(List<List<Neighbor>> neighborsByVertex) {
32	        List<List<Neighbor>> copiedNeighbors = new ArrayList<>(neighborsByVertex.size());
33	
34	        for (List<Neighbor> neighbors : neighborsByVertex) {
35	            copiedNeighbors.add(List.copyOf(neighbors));
36	        }
37	
38	        return List.copyOf(copiedNeighbors);
39	    }
40	}

 1	final class PrimsMinimumSpanningTree implements MinimumSpanningTreeAlgorithm {
 2	    private static final int START_VERTEX = 0;
 3	
 4	    @Override
 5	    public MstResult compute(Graph graph) {
 6	        PrimVertexState vertexState = new PrimVertexState(graph.vertexCount(), START_VERTEX);
 7	
 8	        for (int visitedVertices = 0; visitedVertices < graph.vertexCount(); visitedVertices++) {
 9	            int currentVertex = vertexState.nextVertexToInclude();
10	            if (currentVertex == -1) {
11	                throw new IllegalStateException("Graph must be connected.");
12	            }
13	
14	            vertexState.include(currentVertex);
15	            relaxAdjacentVertices(graph, currentVertex, vertexState);
16	        }
17	
18	        return vertexState.buildResult();
19	    }
20	
21	    private static void relaxAdjacentVertices(Graph graph, int currentVertex, PrimVertexState vertexState) {
22	        for (Neighbor neighbor : graph.neighborsOf(currentVertex)) {
23	            int candidateVertex = neighbor.vertex();
24	            if (vertexState.isIncluded(candidateVertex)) {
25	                continue;
26	            }
27	
28	            vertexState.considerEdge(currentVertex, candidateVertex, neighbor.weight());
29	        }
30	    }
31	}

